def is_palindrome(s):
    return s == s[::-1]

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    costs = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append(s)
        costs.append(c)
        idx += 2

    min_cost = float('inf')

    # Check single strings
    for i in range(N):
        if is_palindrome(strings[i]):
            if costs[i] < min_cost:
                min_cost = costs[i]

    # Check pairs
    for i in range(N):
        for j in range(N):
            s1 = strings[i]
            s2 = strings[j]
            if is_palindrome(s1 + s2) or is_palindrome(s2 + s1):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total

