        s = input[idx]
        c = int(input[idx+1])
        strings.append(s)
        costs.append(c)
        idx += 2

    min_cost = float('inf')

    # Check for k=1
    for i in range(N):
        if is_palindrome(strings[i]):
            if costs[i] < min_cost:
                min_cost = costs[i]

    # Check for k=2
    for i in range(N):
        for j in range(N):
            s1 = strings[i]
            s2 = strings[j]
            t1 = s1 + s2
            if is_palindrome(t1):
                cost = costs[i] + costs[j]
                if cost < min_cost:
