import sys

def main():
    N, K = map(int, sys.stdin.readline().split())
    R, S, P = map(int, sys.stdin.readline().split())
    T = sys.stdin.readline().strip()

    groups = [[] for _ in range(K)]
    for i in range(N):
        group_idx = i % K
        groups[group_idx].append(T[i])

    total = 0
    for group in groups:
        if not group:
            continue
        first_move = group[0]
        if first_move == 'r':
            prev_r, prev_p, prev_s = 0, P, 0
        elif first_move == 'p':
            prev_r, prev_p, prev_s = 0, 0, S
        else:  # 's'
            prev_r, prev_p, prev_s = R, 0, 0

        for i in range(1, len(group)):
            current_move = group[i]
            if current_move == 'r':
                curr_r, curr_p, curr_s = 0, P, 0
            elif current_move == 'p':
                curr_r, curr_p, curr_s = 0, 0, S
            else:  # 's'
                curr_r, curr_p, curr_s = R, 0, 0

            new_r = max(prev_p, prev_s) + curr_r
            new_p = max(prev_r, prev_s) + curr_p
            new_s = max(prev_r, prev_p) + curr_s
            prev_r, prev_p, prev_s = new_r, new_p, new_s

        total += max(prev_r, prev_p, prev_s)

    print(total)

