from functools import lru_cache

MOD = 10**9 + 7

def main():
    import sys
    input = sys.stdin.read
    n, k = map(int, input().split())

    @lru_cache(maxsize=None)
    def dfs(pos, used, current_sum):
        if pos > n:
            return 1 if current_sum == k else 0
        res = 0
        for x in range(1, n+1):
            if not (used & (1 << (x-1))):
                new_used = used | (1 << (x-1))
                new_sum = current_sum + abs(pos - x)
                res += dfs(pos + 1, new_used, new_sum)
                res %= MOD
        return res

    print(dfs(1, 0, 0))

