def main():
    n, k = map(int, sys.stdin.readline().split())
    if k % 2 != 0:
        print(0)
        return
    target = k // 2

    @lru_cache(maxsize=None)
    def dp(pos, mask, s):
        if pos == n:
            return 1 if s == target else 0
        res = 0
        for x in range(1, n+1):
            if not (mask & (1 << (x-1))):
                new_mask = mask | (1 << (x-1))
                contribution = abs(pos + 1 - x)
                res += dp(pos + 1, new_mask, s + contribution)
                res %= MOD
        return res

    print(dp(0, 0, 0))

