from collections import defaultdict, deque

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = []
    B = []
    for i in range(N):
        a = int(data[1 + 2*i])
        b = int(data[2 + 2*i])
        A.append(a)
        B.append(b)

    # For each person, determine a_min, a_max, b_min, b_max
    a_min = [0]*N
    a_max = [0]*N
    b_min = [0]*N
    b_max = [0]*N
    for i in range(N):
        a = A[i]
        b = B[i]
        if a != -1:
            a_min[i] = a_max[i] = a
        else:
            a_min[i] = 1
            a_max[i] = 2*N - 1
        if b != -1:
            b_min[i] = b_max[i] = b
        else:
            b_min[i] = 1
            b_max[i] = 2*N

    # Build graph
    graph = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            # Check if intervals could possibly overlap
            if a_min[i] < b_max[j] and a_min[j] < b_max[i]:
                graph[i].append(j)

    # Find connected components
    visited = [False]*N
    components = []
    for i in range(N):
        if not visited[i]:
            q = deque()
            q.append(i)
            visited[i] = True
            component = []
            while q:
                u = q.popleft()
                component.append(u)
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        q.append(v)
            components.append(component)

    # For each component, determine L
    possible = True
    # For each component, store the required L
    component_L = []
    for comp in components:
        # Check if any person in the component has fixed A and B
        L = None
        for i in comp:
            a = A[i]
            b = B[i]
            if a != -1 and b != -1:
                current_L = b - a
                if L is None:
                    L = current_L
                else:
                    if current_L != L:
                        possible = False
                        break
        if not possible:
            break
        component_L.append(L)

    if not possible:
        print("No")
        return

    # Now, for each component, assign A and B
    # We need to check if it's possible to assign A and B for each person in the component
    # with B = A + L, and all values are distinct and within 1 to 2N
    used = set()
    for comp_idx, comp in enumerate(components):
        L = component_L[comp_idx]
        # For each person in the component, determine their A and B
        # If A is fixed, B = A + L
        # If B is fixed, A = B - L
        # If both are fixed, check if B - A == L
        # If neither is fixed, choose A and B = A + L
        # We need to collect all A and B values
        assigned = {}
        for i in comp:
            a = A[i]
            b = B[i]
            if a != -1 and b != -1:
                if b - a != L:
                    possible = False
                    break
                # Check if a and b are already used
                if a in used or b in used:
                    possible = False
                    break
                used.add(a)
                used.add(b)
                assigned[i] = (a, b)
            elif a != -1:
                # B is missing, so B = a + L
                b_val = a + L
                if b_val > 2*N or b_val in used or a in used:
                    possible = False
                    break
                used.add(a)
                used.add(b_val)
                assigned[i] = (a, b_val)
            elif b != -1:
                # A is missing, so A = b - L
                a_val = b - L
                if a_val < 1 or a_val in used or b in used:
                    possible = False
                    break
                used.add(a_val)
                used.add(b)
                assigned[i] = (a_val, b)
            else:
                # Both are missing, choose a and b = a + L
                # Find the smallest available a
                for a_val in range(1, 2*N - L + 1):
                    if a_val not in used and (a_val + L) not in used:
                        used.add(a_val)
                        used.add(a_val + L)
                        assigned[i] = (a_val, a_val + L)
                        break
                else:
                    possible = False
                    break
        if not possible:
            break

    if possible:
        print("Yes")
    else:
        print("No")

