def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1

    INF = float('inf')
    dist = [[INF] * (N + 1) for _ in range(N + 1)]
    edges = []

    for i in range(1, N + 1):
        dist[i][i] = 0

    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        edges.append((a, b, c))
        dist[a][b] = c
        dist[b][a] = c

    # Floyd-Warshall algorithm
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    count = 0
    for a, b, c in edges:
        used = False
        for u in range(1, N + 1):
            for v in range(1, N + 1):
                if u == v:
                    continue
                if (dist[u][a] + c + dist[b][v] == dist[u][v]) or (dist[u][b] + c + dist[a][v] == dist[u][v]):
                    used = True
                    break
            if used:
                break
        if not used:
            count += 1

    print(count)

