    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1

    edges = []
    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        edges.append((a, b, c))

    INF = float('inf')
    distance = [[INF] * (N + 1) for _ in range(N + 1)]

    for i in range(1, N + 1):
        distance[i][i] = 0

    for a, b, c in edges:
        distance[a][b] = c
        distance[b][a] = c

    # Floyd-Warshall algorithm
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]

    count = 0
    for a, b, c in edges:
        flag = False
        for u in range(1, N + 1):
            for v in range(1, N + 1):
                if u == v:
                    continue
                if distance[u][a] + c + distance[b][v] == distance[u][v]:
                    flag = True
                    break
                if distance[u][b] + c + distance[a][v] == distance[u][v]:
                    flag = True
                    break
            if flag:
                break
        if not flag:
            count += 1
    print(count)

