def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    allowed_digits = list(map(int, input[2:2+M]))

    costs = {
        1:2,
        2:5,
        3:5,
        4:4,
        5:5,
        6:6,
        7:3,
        8:7,
        9:6
    }

    sorted_allowed = sorted(allowed_digits, reverse=True)

    INF = float('-inf')
    dp = [INF] * (N + 1)
    dp[0] = 0

    for i in range(1, N + 1):
        for d in allowed_digits:
            cost = costs[d]
            if i >= cost and dp[i - cost] != INF:
                if dp[i - cost] + 1 > dp[i]:
                    dp[i] = dp[i - cost] + 1

    K = dp[N]

    result = []
    remaining = N
    digits_left = K

    for _ in range(K):
        for d in sorted_allowed:
            cost = costs[d]
            if remaining >= cost and dp[remaining - cost] == digits_left - 1:
                result.append(str(d))
                remaining -= cost
                digits_left -= 1
                break

    print(''.join(result))

