def main():
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()

    def match_winner(a, b):
        if a == b:
            return a
        if (a == 'R' and b == 'S') or (a == 'P' and b == 'R') or (a == 'S' and b == 'P'):
            return a
        else:
            return b

    memo = {}

    def get_winner(start, m):
        if (start, m) in memo:
            return memo[(start, m)]
        if m == 0:
            res = s[start]
            memo[(start, m)] = res
            return res
        power = pow(2, m-1, n)
        right_start = (start + power) % n
        left_winner = get_winner(start, m-1)
        right_winner = get_winner(right_start, m-1)
        winner = match_winner(left_winner, right_winner)
        memo[(start, m)] = winner
        return winner

    result = get_winner(0, k)
    print(result)

