from functools import lru_cache

def main():
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()

    # Precompute pow2 array where pow2[m] = 2^m mod n
    pow2 = [1] * (k + 1)
    for i in range(1, k + 1):
        pow2[i] = (pow2[i-1] * 2) % n

    @lru_cache(maxsize=None)
    def get_winner(start_mod, m):
        if m == 0:
            return s[start_mod]
        # Split into left and right halves
        left_winner = get_winner(start_mod, m-1)
        right_start_mod = (start_mod + pow2[m-1]) % n
        right_winner = get_winner(right_start_mod, m-1)
        # Compare the two winners
        if left_winner == right_winner:
            return left_winner
        if (left_winner == 'R' and right_winner == 'S') or \
           (left_winner == 'P' and right_winner == 'R') or \
           (left_winner == 'S' and right_winner == 'P'):
            return left_winner
        else:
            return right_winner

    result = get_winner(0, k)
    print(result)

