import sys

def factorize(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 1
    if x > 1:
        factors[x] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for prime, exp in factors.items():
        current_length = len(divisors)
        prime_powers = [prime**e for e in range(1, exp+1)]
        for d in divisors[:current_length]:
            for p in prime_powers:
                divisors.append(d * p)
    return divisors

def main():
    N = int(sys.stdin.readline())

    # Case B: divisors of N-1 >= 2
    x = N - 1
    if x == 0:
        case_b = 0
    else:
        factors_b = factorize(x)
        divisors_b = get_divisors(factors_b)
        case_b = len([d for d in divisors_b if d >= 2])

    # Case A: divisors of N >= 2, check condition
    x = N
    factors_a = factorize(x)
    divisors_a = get_divisors(factors_a)
    case_a = 0
    for K in divisors_a:
        if K < 2:
            continue
        temp = N
        while temp % K == 0:
            temp = temp // K
        r = temp
        if r % K == 1:
            case_a += 1

    total = case_a + case_b
    print(total)

