    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        matrix.append(row)
        idx += N

    # Process rows
    dsu_rows = DSU(N)
    for i in range(N):
        for j in range(i+1, N):
            valid = True
            for x in range(N):
                if matrix[i][x] + matrix[j][x] > K:
                    valid = False
                    break
            if valid:
                dsu_rows.union(i, j)

    # Process columns
    dsu_cols = DSU(N)
    for x in range(N):
        for y in range(x+1, N):
            valid = True
            for i in range(N):
                if matrix[i][x] + matrix[i][y] > K:
                    valid = False
                    break
            if valid:
                dsu_cols.union(x, y)

    # Compute factorials up to N
    max_fact = N
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i-1] * i % mod

    # Get row component sizes
    roots_rows = set()
    for i in range(N):
        roots_rows.add(dsu_rows.find(i))
    row_product = 1
    for root in roots_rows:
