    for i in range(1, N+1):
        for j in range(i+1, N+1):
            matches.append((i, j))
    num_matches = len(matches)
    match_to_index = {(i, j): idx for idx, (i, j) in enumerate(matches)}

    adj = [[] for _ in range(num_matches)]
    in_degree = [0] * num_matches

    for i in range(N):
        player = i + 1
        opp_list = opponents[i]
        for k in range(len(opp_list) - 1):
            prev_opponent = opp_list[k]
            next_opponent = opp_list[k+1]
            prev_match = (min(player, prev_opponent), max(player, prev_opponent))
            next_match = (min(player, next_opponent), max(player, next_opponent))
            u = match_to_index[prev_match]
            v = match_to_index[next_match]
            adj[u].append(v)
            in_degree[v] += 1

    queue = deque()
    for idx in range(num_matches):
        if in_degree[idx] == 0:
            queue.append(idx)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

