def main():
    N = int(sys.stdin.readline())
    A = []
    for _ in range(N):
        A.append(list(map(int, sys.stdin.readline().split())))

    # Generate sequences for each player
    sequences = [[] for _ in range(N+1)]  # 1-based indexing
    for i in range(1, N+1):
        seq = []
        for j in A[i-1]:
            u = i
            v = j
            match = (min(u, v), max(u, v))
            seq.append(match)
        sequences[i] = seq

    # Build adjacency list and reverse_adj
    adj = defaultdict(list)
    reverse_adj = defaultdict(list)
    for i in range(1, N+1):
        seq = sequences[i]
        for k in range(len(seq) - 1):
            u = seq[k]
            v = seq[k+1]
            adj[u].append(v)
            reverse_adj[v].append(u)

    # Collect all matches
    matches = set()
    for i in range(1, N+1):
        for match in sequences[i]:
            matches.add(match)

    # Compute in_degree
    in_degree = defaultdict(int)
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1

    # Kahn's algorithm
    queue = deque()
    topological_order = []
    for match in matches:
        if in_degree[match] == 0:
            queue.append(match)

    while queue:
        u = queue.popleft()
        topological_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topological_order) != len(matches):
        print(-1)
        return

    # Compute earliest_day
    earliest_day = {}
    for match in topological_order:
        max_prev = 0
        for pred in reverse_adj[match]:
            if earliest_day[pred] > max_prev:
                max_prev = earliest_day[pred]
        earliest_day[match] = max_prev + 1

    max_days = max(earliest_day.values())
    print(max_days)

