    adj = defaultdict(list)
    in_deg = defaultdict(int)
    all_matches = set()

    for i in range(1, N+1):
        for j in range(len(matches[i]) - 1):
            prev_match = matches[i][j]
            curr_match = matches[i][j+1]
            adj[prev_match].append(curr_match)
            in_deg[curr_match] += 1
            all_matches.add(prev_match)
            all_matches.add(curr_match)

    # Kahn's algorithm
