def compute_sum(n):
    if n < 0:
        return 0
    # Convert n to binary as a list of integers (most significant bit first)
    bits = []
    if n == 0:
        bits = [0]
    else:
        while n > 0:
            bits.append(n & 1)
            n >>= 1
        bits = bits[::-1]  # Reverse to get most significant bit first
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, count):
        if pos == len(bits):
            return pow(2, count, MOD)
        limit = bits[pos] if tight else 1
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_count = count + (1 if d == 1 else 0)
            total += dp(pos + 1, new_tight, new_count)
            total %= MOD  # To prevent overflow
        return total

    return dp(0, True, 0)

