            new_cnt = cnt
            if not new_leading_zero:
                if d != 0:
                    new_cnt += 1
            res += dp(pos + 1, new_cnt, new_tight, new_leading_zero)
        return res

    result = dp(0, 0, True, True)
    print(result)

