                if (mask & (1 << i)) and (mask & (1 << (i+1))):
                    valid = False
                    break
            if valid:
                patterns.append(mask)
        return patterns

    patterns = generate_patterns(W)

    dp_prev = [0] * (W + 1)
    dp_prev[1] = 1

    for _ in range(H):
        dp_current = [0] * (W + 1)
        for pos_prev in range(1, W + 1):
            if dp_prev[pos_prev] == 0:
                continue
            for pattern in patterns:
                if pos_prev > 1 and (pattern & (1 << (pos_prev - 2))):
                    new_pos = pos_prev - 1
                elif pos_prev < W and (pattern & (1 << (pos_prev - 1))):
                    new_pos = pos_prev + 1
                else:
                    new_pos = pos_prev
                dp_current[new_pos] = (dp_current[new_pos] + dp_prev[pos_prev]) % MOD
        dp_prev = dp_current

    print(dp_prev[K] % MOD)

