def main():
    import sys
    from collections import defaultdict

    N = int(sys.stdin.readline())
    forbidden = {'AGC', 'ACG', 'GAC'}

    # dp[i][a][b][c] represents the number of valid strings of length i ending with a, b, c
    # Initially, for length 0, the state is (None, None, None)
    dp = defaultdict(int)
    dp[(None, None, None)] = 1

    for _ in range(N):
        new_dp = defaultdict(int)
        for state, count in dp.items():
            a, b, c = state
            for char in ['A', 'C', 'G', 'T']:
                # New state is (b, c, char)
                new_state = (b, c, char)
                # Check if any of the four combinations is forbidden
                # 1. b, c, char
                s1 = ''.join([b, c, char]) if b is not None and c is not None else None
                if s1 in forbidden:
                    continue
                # 2. b, char, c
                s2 = ''.join([b, char, c]) if b is not None and c is not None else None
                if s2 in forbidden:
                    continue
                # 3. a, c, char
                s3 = ''.join([a, c, char]) if a is not None and c is not None else None
                if s3 in forbidden:
                    continue
                # 4. b, a, c
                s4 = ''.join([b, a, c]) if b is not None and a is not None and c is not None else None
                if s4 in forbidden:
                    continue
                new_dp[new_state] = (new_dp[new_state] + count) % MOD
        dp = new_dp

    result = sum(dp.values()) % MOD
    print(result)

