    w0 = items[0][0]
    groups = [[] for _ in range(4)]
    for w, v in items:
        if w == w0:
            groups[0].append(v)
        elif w == w0 + 1:
            groups[1].append(v)
        elif w == w0 + 2:
            groups[2].append(v)
        elif w == w0 + 3:
            groups[3].append(v)

    # Compute prefix sums for each group
    prefix_sums = []
    for group in groups:
        group.sort(reverse=True)
        ps = [0]
        for val in group:
            ps.append(ps[-1] + val)
        prefix_sums.append(ps)

    max_total = 0
    for T in range(0, N+1):
        S = W - T * w0
        if S < 0:
            continue
        s_max = min(S, 3 * T)
        if s_max < 0:
            continue
        # Initialize dp
        dp = [[-math.inf] * (s_max + 1) for _ in range(T + 1)]
        dp[0][0] = 0
        # Process groups 1, 2, 3
        for group_idx in [1, 2, 3]:
            group_weight = group_idx
            group = groups[group_idx]
            group_prefix = prefix_sums[group_idx]
            max_k = min(len(group), T)
            # Iterate in reverse to avoid overwriting
            for t in range(T, -1, -1):
                for s in range(s_max, -1, -1):
                    if dp[t][s] == -math.inf:
                        continue
                    # Try taking k items from this group
