                            continue
                        new_s = s + k * group_weight
                        if new_s > s_max:
                            continue
                        new_t = t + k
                        if dp[new_t][new_s] < dp[t][s] + group_prefix[k]:
                            dp[new_t][new_s] = dp[t][s] + group_prefix[k]
        # Check all possible t and s
        for t in range(T + 1):
            for s in range(s_max + 1):
                if dp[t][s] != -math.inf:
                    a0 = T - t
                    if a0 >= 0 and a0 <= len(prefix_sums[0]) - 1:
                        current_value = prefix_sums[0][a0] + dp[t][s]
                        if current_value > max_total:
