def main():
    n, W = map(int, sys.stdin.readline().split())
    items = []
    for _ in range(n):
        w, v = map(int, sys.stdin.readline().split())
        items.append((w, v))

    w0 = items[0][0]
    groups = [[], [], [], []]
    for w, v in items:
        d = w - w0
        groups[d].append(v)

    # Compute prefix sums for each group
    prefix_sums = []
    for group in groups:
        group.sort(reverse=True)
        prefix = [0]
        for val in group:
            prefix.append(prefix[-1] + val)
        prefix_sums.append(prefix)

    max_value = 0
    for k in range(0, n + 1):
        e = W - w0 * k
        if e < 0:
            continue
        len1 = len(groups[1])
        len2 = len(groups[2])
        len3 = len(groups[3])
        # Iterate x1, x2, x3
        for x1 in range(0, min(len1, k) + 1):
            for x2 in range(0, min(len2, k - x1) + 1):
                for x3 in range(0, min(len3, k - x1 - x2) + 1):
                    total_items = x1 + x2 + x3
                    if total_items > k:
                        continue
                    extra = x1 + 2 * x2 + 3 * x3
                    if extra > e:
                        continue
                    x0 = k - total_items
                    if x0 < 0 or x0 > len(groups[0]):
                        continue
                    val = (prefix_sums[0][x0] if x0 <= len(prefix_sums[0])-1 else 0) + \
                          (prefix_sums[1][x1] if x1 <= len(prefix_sums[1])-1 else 0) + \
                          (prefix_sums[2][x2] if x2 <= len(prefix_sums[2])-1 else 0) + \
                          (prefix_sums[3][x3] if x3 <= len(prefix_sums[3])-1 else 0)
                    if val > max_value:
