        for v, weight in adj_reversed[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                heapq.heappush(heap, (dist[v], v))

    # Read the wall
    total = 0
    for _ in range(H):
        row = list(map(int, input[ptr:ptr+W]))
        ptr += W
        for cell in row:
            if cell != -1:
