def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    A = list(map(int, input[2:2+N]))
    A.sort()
    low = -10**18
    high = 10**18

    def count_pairs(mid):
        count = 0
        for i in range(N):
            if i >= N-1:
                break
            if A[i] > 0:
                if mid < 0:
                    continue
                target = mid / A[i]
                left = i + 1
                right = N
                while left < right:
                    mid_b = (left + right) // 2
                    if A[mid_b] <= target:
                        left = mid_b + 1
                    else:
                        right = mid_b
                count += left - i - 1
            elif A[i] < 0:
                if mid < 0:
                    target = mid / A[i]
                    left = i + 1
                    right = N
                    while left < right:
                        mid_b = (left + right) // 2
                        if A[mid_b] >= target:
                            right = mid_b
                        else:
                            left = mid_b + 1
                    count += N - left
                else:
                    target = mid / A[i]
                    pos = bisect.bisect_right(A, 0, i+1, N)
                    count_positive = N - pos
                    left = bisect.bisect_left(A, target, i+1, N)
                    count_negative = max(0, pos - left)
                    count += count_positive + count_negative
            else:
                if mid >= 0:
                    count += N - (i+1)
        return count

    while low < high:
        mid = (low + high) // 2
        c = count_pairs(mid)
        if c >= K:
            high = mid
        else:
            low = mid + 1
    print(low)

