    def check_zero_x():
        non_moving_x_current = [(x, y, d) for x, y, d in points if d in ['U', 'D']]
        moving_x_current = [(x, y, d) for x, y, d in points if d in ['R', 'L']]
        if non_moving_x_current:
            x_vals = [x for x, y, d in non_moving_x_current]
            first_x = x_vals[0]
            for x in x_vals:
                if x != first_x:
                    return False
            X = first_x
            if not moving_x_current:
                return True
            t_list = []
            for x, y, d in moving_x_current:
                if d == 'R':
                    t = X - x
                else:
                    t = x - X
                t_list.append(t)
            first_t = t_list[0]
            for t in t_list:
                if t != first_t or t < 0:
                    return False
            return True
        else:
            if not moving_x_current:
                return True
            p1 = moving_x_current[0]
            p2 = moving_x_current[1]
            if p1[2] == p2[2]:
                if p1[0] != p2[0]:
                    return False
                return True
            else:
                d1 = 1 if p1[2] == 'R' else -1
                d2 = 1 if p2[2] == 'R' else -1
                numerator = p1[0] - p2[0]
                denominator = d2 - d1
                if denominator == 0:
                    return False
                t = numerator / denominator
                if t < 0:
                    return False
                for x, y, d in moving_x_current:
                    dx = 1 if d == 'R' else -1
                    expected = p1[0] + d1 * t
                    actual = x + dx * t
                    if abs(actual - expected) > 1e-9:
                        return False
                return True

    def check_zero_y():
        non_moving_y_current = [(x, y, d) for x, y, d in points if d in ['R', 'L']]
        moving_y_current = [(x, y, d) for x, y, d in points if d in ['U', 'D']]
        if non_moving_y_current:
