                d2 = 1 if p2[2] == 'U' else -1
                numerator = p1[1] - p2[1]
                denominator = d2 - d1
                if denominator == 0:
                    return False
                t = numerator / denominator
                if t < 0:
                    return False
                for x, y, d in moving_y_current:
                    dy = 1 if d == 'U' else -1
                    expected = p1[1] + d1 * t
                    actual = y + dy * t
                    if abs(actual - expected) > 1e-9:
                        return False
                return True

    if check_zero_x() or check_zero_y():
        print(0)
        return

    def compute_product(t):
        max_x_moving = -float('inf')
        min_x_moving = float('inf')
        for x, y, d in moving_x:
            if d == 'R':
                x_val = x + t
            else:
                x_val = x - t
            if x_val > max_x_moving:
                max_x_moving = x_val
            if x_val < min_x_moving:
                min_x_moving = x_val
        max_x_non_moving = max([x for x, y, d in non_moving_x])
        min_x_non_moving = min([x for x, y, d in non_moving_x])
        x_max = max(max_x_moving, max_x_non_moving)
        x_min = min(min_x_moving, min_x_non_moving)

        max_y_moving = -float('inf')
        min_y_moving = float('inf')
        for x, y, d in moving_y:
            if d == 'U':
                y_val = y + t
            else:
                y_val = y - t
            if y_val > max_y_moving:
                max_y_moving = y_val
            if y_val < min_y_moving:
                min_y_moving = y_val
        max_y_non_moving = max([y for x, y, d in non_moving_y])
        min_y_non_moving = min([y for x, y, d in non_moving_y])
        y_max = max(max_y_moving, max_y_non_moving)
        y_min = min(min_y_moving, min_y_non_moving)
        return (x_max - x_min) * (y_max - y_min)

    low = 0.0
    high = 1e14
    for _ in range(100):
        if high - low < 1e-9:
            break
        mid1 = low + (high - low)/3
        mid2 = high - (high - low)/3
        f1 = compute_product(mid1)
