        moving_x = []
        for x, y, d in points:
            if d in ['U', 'D']:
                static_x.append(x)
            else:
                moving_x.append((x, d))
        if static_x:
            x0 = static_x[0]
            for x in static_x:
                if x != x0:
                    return False
        else:
            if len(moving_x) == 0:
                return True
            if len(moving_x) < 2:
                return True
            x1, d1 = moving_x[0]
            x2, d2 = moving_x[1]
            d1_coeff = 1 if d1 == 'R' else -1
            d2_coeff = 1 if d2 == 'R' else -1
            numerator = x2 - x1
            denominator = d1_coeff - d2_coeff
            if denominator == 0:
                if x1 != x2:
                    return False
                else:
                    x0 = x1
                    for x, d in moving_x:
                        if x != x0:
                            return False
                    return True
            else:
                t = numerator / denominator
                x0 = x1 + d1_coeff * t
                for x, d in moving_x:
                    coeff = 1 if d == 'R' else -1
                    if abs(x + coeff * t - x0) > 1e-9:
                        return False
                return True
        if not moving_x:
            return True
        x0 = static_x[0]
        first_x, first_d = moving_x[0]
