def max_subset_xor(arr):
    basis = [0] * 60
    for num in arr:
        if num == 0:
            continue
        current = num
        for i in reversed(range(60)):
            if (current >> i) & 1:
                if basis[i] == 0:
                    basis[i] = current
                    break
                else:
                    current ^= basis[i]
                if current == 0:
                    break
    max_xor = 0
    for i in reversed(range(60)):
        if basis[i] and (max_xor ^ basis[i]) > max_xor:
            max_xor ^= basis[i]
    return max_xor

