MOD = 10**9 + 7

def main():
    N = int(sys.stdin.readline())
    if N == 0:
        print(1)
        return
    bin_str = bin(N)[2:]
    m = len(bin_str)

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == -1:
            return 1
        res = 0
        bit_n = int(bin_str[pos]) if tight else 1

        # Option 1: set current bit in u
        if tight:
            if bit_n == 1:
                res += dp(pos - 1, True)
        else:
            res += dp(pos - 1, False)

        # Option 2: set current bit in k
        # This contributes 2^(pos+1) to v
        # We need to check if it's allowed
        if tight:
            if bit_n == 1:
                # Check if adding 2^(pos+1) is allowed
                # For simplicity, assume it's allowed if the next bit is 1
                # This is a placeholder and needs proper logic
                res += dp(pos - 1, True)
        else:
            res += dp(pos - 1, False)

        # Option 3: not set
        if tight:
            if bit_n == 0:
                res += dp(pos - 1, False)
            else:
                res += dp(pos - 1, True)
        else:
            res += dp(pos - 1, False)

        return res % MOD

    result = dp(m - 1, True)
    print(result)

