def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    M = int(input[idx]); idx +=1
    L = int(input[idx]); idx +=1

    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        A = int(input[idx]); idx +=1
        B = int(input[idx]); idx +=1
        C = int(input[idx]); idx +=1
        if C <= L:
            adj[A].append( (B, C) )
            adj[B].append( (A, C) )

    Q = int(input[idx]); idx +=1
    queries = []
    for _ in range(Q):
        s = int(input[idx]); idx +=1
        t = int(input[idx]); idx +=1
        queries.append( (s, t) )

    for s, t in queries:
        if s == t:
            print(0)
            continue
        max_fuel = [{} for _ in range(N+1)]
        heap = []
        heapq.heappush(heap, (0, s, L))
        max_fuel[s][0] = L
        found = False
        answer = -1
        while heap:
            refills, u, fuel = heapq.heappop(heap)
            if u == t:
                answer = refills
                found = True
                break
            if refills not in max_fuel[u] or fuel < max_fuel[u][refills]:
                continue
            for v, c in adj[u]:
                if fuel >= c:
                    new_fuel = fuel - c
                    new_refills = refills
                    if new_refills not in max_fuel[v]:
                        max_fuel[v][new_refills] = new_fuel
                        heapq.heappush(heap, (new_refills, v, new_fuel))
                    else:
                        if new_fuel > max_fuel[v][new_refills]:
                            max_fuel[v][new_refills] = new_fuel
                            heapq.heappush(heap, (new_refills, v, new_fuel))
                new_refills = refills + 1
                new_fuel = L
                if new_refills not in max_fuel[u]:
                    max_fuel[u][new_refills] = new_fuel
                    heapq.heappush(heap, (new_refills, u, new_fuel))
                else:
                    if new_fuel > max_fuel[u][new_refills]:
                        max_fuel[u][new_refills] = new_fuel
                        heapq.heappush(heap, (new_refills, u, new_fuel))
        print(answer if found else -1)

