import sys

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 2)

    def update(self, index, delta=1):
        while index <= self.n:
            self.tree[index] += delta
            index += index & -index

    def query(self, index):
        res = 0
        while index > 0:
            res += self.tree[index]
            index -= index & -index
        return res

def count_inversions(P):
    n = len(P)
    max_val = n
    ft = FenwickTree(max_val)
    inv_count = 0
    for i in range(n-1, -1, -1):
        inv_count += ft.query(P[i]-1)
        ft.update(P[i])
    return inv_count

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    P = list(map(int, input[1:N+1]))

    inv_count = count_inversions(P)
    if (inv_count % 2) != ((N-1) % 2):
        print(-1)
        return

    P = P.copy()
    pos = [0] * (N + 1)
    for i in range(N):
        pos[P[i]] = i + 1

    swaps = []
    for i in range(N, 0, -1):
        if P[i-1] == i:
            continue
        j = pos[i]
        for k in range(j, i):
            x = P[k-1]
            y = P[k]
            P[k-1], P[k] = y, x
            swaps.append(k)
            pos[x] = k + 1
            pos[y] = k

    if len(swaps) == N-1:
        for s in swaps:
            print(s)
    else:
        print(-1)

